import React from 'react';
import { render } from 'react-email';
import { writeFile } from 'node:fs/promises';
import SubmissionEmail from '../emails/submission.mjs';

const html = await render(React.createElement(SubmissionEmail));
await writeFile(new URL('../server/email-template.generated.js', import.meta.url),
  '// Generated by scripts/build-email.mjs. Edit emails/submission.mjs.\nexport default ' + JSON.stringify(html) + ';\n');
